for row in REGIONS:
 binary=bs[row['module']];start=int(row['start'],16);end=int(row['end'],16)+0;raw=binary.data[binary.off(start):binary.off(start)+end-start];assert hashlib.sha256(raw).hexdigest()==row['sha256']
 xs=list(md.disasm(raw,start));assert xs[-1].address+xs[-1].size==end;actual={(hex(i.address),i.mnemonic,i.op_str)for i in xs}
 for pin in row['pins']:assert tuple(pin)in actual,pin
 if row['extent']!='complete-Ghidra-body-region':assert xs[-1].mnemonic=='ret'and not any(i.mnemonic.startswith(('j','call'))for i in xs)
for row in BINDINGS:
 binary=bs[row['module']];start=binary.off(int(row['start'],16));assert hashlib.sha256(binary.data[start:start+row['length']]).hexdigest()==row['sha256']
for row in OWNERS:
 binary=bs[row['module']];d=binary.qwords(int(row['descriptor'],16),4);assert d[1]&0xffffffff==int(row['type'],16)and d[1]>>32==int(row['base'],16)
 if row['metadata']:
  assert d[3]==int(row['metadata'],16);m=binary.qwords(d[3],4);assert m[1]==int(row['primary'],16)and m[3]==int(row['callback'],16)and binary.qwords(m[2],3)==tuple(int(x,16)for x in row['constructors']);assert binary.qwords(m[1],4)==tuple(int(x,16)for x in row['methods']);assert binary.qwords(int(row['codecTable'],16),3)==tuple(int(x,16)for x in row['codecMethods'])
 else:assert d[3]==0
assert bs['MyScriptEngine.dll'].qwords(0x180229f80+0x10,1)==(0x180109de0,)and bs['MyScriptEngine.dll'].qwords(0x180229f80+0xa8,1)==(0x18010dac0,)
