 magic,n,typ,flags,version=struct.unpack_from('<4sIIHH',resource,at);end=at+8+n;assert magic==b'\x90\xfe\x01\x01'and n>=8 and typ==t and flags==0 and version==v and end<=limit
 row=dict(start=at,end=end,type=hex(t),version=hex(v),sha256=hashlib.sha256(resource[at:end]).hexdigest());frames.append(row);return end
